import{_ as e,o as t,c as d,a2 as o}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Armas y tipos de daño","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/weapons-and-damage.md","filePath":"es/guide/combat/weapons-and-damage.md"}'),r={name:"es/guide/combat/weapons-and-damage.md"};function n(s,a,i,l,c,m){return t(),d("div",null,[...a[0]||(a[0]=[o('<h1 id="weapons-and-damage-types" tabindex="-1">Armas y tipos de daño <a class="header-anchor" href="#weapons-and-damage-types" aria-label="Enlace permanente a &quot;Armas y tipos de daño&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto para las identidades de armas · Experimental para los valores numéricos · Aceptado para la separación entre salud y trauma.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Espada, lanza y martillo plantean problemas diferentes de distancia, ritmo y stamina.</li><li>El daño global y Local Trauma son distintos; la calidad no elimina los costes de cada arma.</li><li>Los valores indicados son de prueba, con estado Experimental, no equilibrio en vivo.</li></ul><p>Las armas deberían crear problemas tácticos diferentes. La calidad de fabricación ayuda al arma a desempeñar su función; no elimina sus costes.</p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Arma</th><th>Alcance</th><th>Ritmo</th><th>Stamina</th><th>Énfasis de trauma</th><th>Fortaleza</th><th>Coste</th></tr></thead><tbody><tr><td>Longsword</td><td>1</td><td>Medio</td><td>Media</td><td>Corte / perforación</td><td>Control del duelo</td><td>Alcance limitado</td></tr><tr><td>Spear</td><td>2; Lunge 3</td><td>Medio</td><td>Media–alta</td><td>Perforación</td><td>Gestión de distancia</td><td>Débil de cerca</td></tr><tr><td>War Hammer</td><td>1; Arc 2</td><td>Lento</td><td>Alta</td><td>Contundente</td><td>Castigar el compromiso</td><td>Fallo costoso</td></tr></tbody></table><p>Los valores pertenecen al perfil de tres armas con estado Experimental. Las descripciones del trauma son identidades, no nuevas fórmulas de fractura, sangrado o penetración.</p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concepto</th><th>Significado</th></tr></thead><tbody><tr><td>Daño global</td><td>Reduce la salud general</td></tr><tr><td>Local Trauma</td><td>Afecta a la región corporal real; independiente de la salud</td></tr><tr><td>Calidad</td><td>Materiales, técnica, consistencia y manejo</td></tr><tr><td>Protección</td><td>La armadura y los escudos interactúan con el ataque real</td></tr></tbody></table><h2 id="trade-offs" tabindex="-1">Ventajas y costes <a class="header-anchor" href="#trade-offs" aria-label="Enlace permanente a &quot;Ventajas y costes&quot;">​</a></h2><ul><li>Un golpe pesado no debe convertir al martillo en la elección universal de mayor DPS.</li><li>La versatilidad de la espada compite con la distancia de la lanza y el compromiso del martillo.</li><li>Hachas y dagas conservan sus identidades propuestas; los arcos no reciben un conjunto numérico en este batch.</li></ul><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un Heavy Blow fallado deja más recuperación que castigar que Basic Slash. Un impacto relativo mayor no garantiza un resultado mejor.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/numeric-prototype.html">Tablas de acciones de tres armas</a> · <a href="/Syrolands-Public/es/guide/items/item-quality.html">Calidad de objetos</a> · <a href="/Syrolands-Public/es/guide/combat/armor-and-protection.html">Armadura</a> · <a href="/Syrolands-Public/es/game-design/combat/weapons-and-damage.html">Especificación completa</a></p><p><span id="choose-a-way-to-fight"></span><span id="read-the-encounter"></span></p>',17)])])}const h=e(r,[["render",n]]);export{u as __pageData,h as default};
